import Foundation

/// One original web built-in template seed (data/templates.ts), English catalog.
/// The bundled JSON is generated by the web's own `seedBuiltinTemplates` and
/// re-verified by apps/client/scripts/native-rich-vectors.ts on every CI run.
public struct BuiltinTemplate: Codable, Equatable, Identifiable {
    public let slug: String
    public let name: String
    public let bodyJson: String
    public let bodyText: String
    public var id: String { "builtin:" + slug }
    /// Unsaved, local-only stand-in (like a web pristine seed): never stored or pushed.
    public var seedRecord: VaultRecord {
        VaultRecord(id: id, clock: 1, body: ["kind": .string("template"), "name": .string(name), "bodyJson": .string(bodyJson), "bodyText": .string(bodyText), "builtin": .string(slug)])
    }
}

public enum BuiltinTemplates {
    public static func load(from data: Data) throws -> [BuiltinTemplate] {
        let list = try JSONDecoder().decode([BuiltinTemplate].self, from: data)
        guard !list.isEmpty, Set(list.map(\.slug)).count == list.count, list.allSatisfy({ !$0.slug.isEmpty }) else { throw ChapterError.corruptData }
        return list
    }
    public static let bundled: [BuiltinTemplate] = {
        #if SWIFT_PACKAGE
        guard let url = Bundle.module.url(forResource: "builtin-templates", withExtension: "json"), let data = try? Data(contentsOf: url) else { return [] }
        return (try? load(from: data)) ?? []
        #else
        return []
        #endif
    }()
    /// Web `supersedeBuiltinSeeds`: a pristine seed is retired once any synced
    /// template record, live OR tombstoned, carries its slug.
    public static func pristine(_ seeds: [BuiltinTemplate], records: [VaultRecord]) -> [BuiltinTemplate] {
        let synced = Set(records.filter { $0.kind == "template" }.compactMap { $0.body["builtin"]?.string })
        return seeds.filter { !synced.contains($0.slug) }
    }
    /// Web `mutateSeeded` on a pristine seed: the first rename or delete forks it
    /// into a real synced record carrying the builtin slug, so other devices
    /// retire their own seed. Native has no stored seed time, so createdAt = now.
    public static func fork(_ seed: BuiltinTemplate, id: String, clock: Int64, name: String? = nil, deleted: Bool = false) throws -> VaultRecord {
        guard !id.isEmpty else { throw ChapterError.unsupported }
        try ProtocolNumbers.validate(clock)
        let now = Double(clock)
        let body: [String: JSONValue] = ["kind": .string("template"), "name": .string(name.map(EntryTemplates.savedName) ?? seed.name), "bodyText": .string(seed.bodyText), "bodyJson": .string(seed.bodyJson), "builtin": .string(seed.slug), "createdAt": .number(now), "updatedAt": .number(now)]
        return VaultRecord(id: id, clock: clock, deleted: deleted, body: body, dirty: true)
    }
}
